<?php require __DIR__.'/includes/app.php'; require __DIR__.'/includes/components.php'; $errors=[];$sent=false;$requestPath=APP_ROOT.'/data/requests.json'; if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_valid((string)($_POST['csrf']??'')))$errors[]='Sessiya xavfsizligi tekshiruvi muvaffaqiyatsiz.';$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$message=trim((string)($_POST['message']??''));if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Ismni to‘g‘ri kiriting.';if(mb_strlen($phone)<7||mb_strlen($phone)>30)$errors[]='Telefon raqamini to‘g‘ri kiriting.';if($email!==''&&(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>160))$errors[]='Email manzili noto‘g‘ri.';if(mb_strlen($message)>1000)$errors[]='Xabar juda uzun.';if(!$errors){$list=json_decode((string)(is_file($requestPath)?file_get_contents($requestPath):'[]'),true);if(!is_array($list)||!array_is_list($list))$list=[];$list[]=['id'=>'REQ-'.date('YmdHis').'-'.random_int(100,999),'name'=>$name,'phone'=>$phone,'email'=>$email,'message'=>$message,'created_at'=>date('Y-m-d H:i:s'),'status'=>'new'];$json=json_encode($list,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($json!==false&&file_put_contents($requestPath,$json.PHP_EOL,LOCK_EX)!==false){$sent=true;$_SESSION['public_csrf']=bin2hex(random_bytes(32));}else$errors[]='So‘rovni saqlashda xatolik yuz berdi.';}} site_header('contact','Bog‘lanish'); ?>
